    if (this.session.sheet() !== sheet) return;
    this.amountDrafts.update((drafts) => {
      const rest = { ...drafts };
      delete rest[plan.id];
      return rest;
    });
    this.changed.emit(saved);
  } catch (e) {
    if (this.session.sheet() !== sheet) return;
